    import random
    import time

    LANGUAGE_WRAPPER = 'Fix a positive integer parameter {alpha}. For each positive integer n with 1 \\le n \\le {n_cap}, consider all nondecreasing sequences of positive reals 0 < a_1 \\le a_2 \\le \\cdots \\le a_n that satisfy the constraint \\(\\sum_{k=1}^n a_k^{\\alpha} = \\sum_{k=1}^n a_k^{-\\alpha}\\). Determine, as an explicit enumerated set, all such integers n for which the inequality \\(\\prod_{k=1}^n a_k^{\\alpha k} \\ge 1\\) must hold for every admissible sequence. Output your result in the format: ### The final answer is: $\\boxed{\\{\\text{list all such } n\\}}$. No interval notation is allowed.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose alpha to be at least 2 to ensure a genuine generalization
alpha = rng.randint(2, 7)
# Ensure n_cap is reasonably large to make enumeration nontrivial
n_cap = rng.randint(4, 12)
return {'alpha': alpha, 'n_cap': n_cap}

